function medianOfUniquenessArray(nums) {
  const n = nums.length;
  const total = n * (n + 1) / 2;
  const need = Math.ceil(total / 2);
  const countAtMost = (limit) => {
    const freq = new Map();
    let left = 0;
    let count = 0;
    for (let right = 0; right < n; right++) {
      freq.set(nums[right], (freq.get(nums[right]) ?? 0) + 1);
      while (freq.size > limit) {
        const value = nums[left];
        freq.set(value, freq.get(value) - 1);
        if (freq.get(value) === 0) freq.delete(value);
        left++;
      }
      count += right - left + 1;
    }
    return count;
  };
  let low = 1;
  let high = new Set(nums).size;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (countAtMost(mid) >= need) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

