function medianOfUniquenessArray(nums) {
  // Build the whole uniqueness array, sort it and take the lower middle entry.
  const counts = [];
  for (let i = 0; i < nums.length; i++) {
    const seen = new Set();
    for (let j = i; j < nums.length; j++) {
      seen.add(nums[j]);
      counts.push(seen.size);
    }
  }
  counts.sort((a, b) => a - b);
  return counts[Math.floor((counts.length - 1) / 2)];
}

