function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : pick(1, 10);
  // The pool sets how often values repeat: a pool of 1 gives a single value, 100000 makes nearly every value distinct.
  const pools = size === 'large' ? [2, 10, 60, 500, 100000] : [1, 2, 3, 5, 100000];
  const pool = pools[pick(0, pools.length - 1)];
  const nums = [];
  while (nums.length < n) {
    const value = pick(1, pool);
    // Short runs of one value add the repeated stretches a window has to absorb.
    const run = rand() < 0.25 ? pick(2, 4) : 1;
    for (let k = 0; k < run && nums.length < n; k++) nums.push(value);
  }
  return [nums];
}
